const D = { energy:.55, depth:.5, hue:210, speed:1, density:.5, scale:1, x:.5, y:.5, style:'smear', act:'wave', seed:0, chroma:.5, warp:.4 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style;
const disp=style==='datamosh', echo=style==='echo', crt=style==='crt', xray=style==='xray';
const chromaOn=style!=='xray';
const act=P.act;

const N=14, sc=0.4;
const bw=Math.max(2,Math.round(W*sc)), bh=Math.max(2,Math.round(Hh*sc));

// ---- ring buffer of downscaled canvas captures (size-keyed) ----
if(!S.ring || S.key!==W+'x'+Hh){
  if(S.ring){ for(const g of S.ring){ try{g.remove();}catch(e){} } }
  S.key=W+'x'+Hh; S.ring=[]; S.head=0;
  for(let i=0;i<N;i++){ const g=createGraphics(bw,bh); g.colorMode(HSB,360,100,100,100); S.ring.push(g); }
}
// capture the current (pre-post) canvas into the new head slot
S.head=(S.head+1)%N;
const cap=S.ring[S.head];
cap.clear();
try{ cap.drawingContext.drawImage(drawingContext.canvas,0,0,W,Hh,0,0,bw,bh); }catch(e){}

// ---- delay wave (scrolls in real time -> never re-phases) ----
const en=clp(P.energy,0,1)*(0.55+0.45*K.intensity);
let dep=clp(P.depth,0,1);
const spd=Math.max(0.05,P.speed);
let waveT=K.t*0.55*spd;
if(act==='pulse'){ dep*= (0.45+0.55*K.swell); }
else if(act==='drift'){ waveT=K.t*0.22*spd; }
else if(act==='stutter'){ waveT=Math.floor(K.beat*2*spd)/2*1.4 + K.t*0.12*spd; }
const maxDelay=Math.max(1,Math.floor(lrp(2,N-2,dep)));
const nb=Math.round(lrp(11,24,clp(P.density,0,1)));
const phX=(P.x-0.5)*4;

drawingContext.imageSmoothingEnabled=true;
noStroke();

// precompute per-band geometry + delayed source once (reused in both passes)
const B=[];
for(let b=0;b<nb;b++){
  const y0=Math.floor(b*Hh/nb), y1=Math.floor((b+1)*Hh/nb), bandH=y1-y0;
  const cy=(b+0.5)/nb;
  const wv=0.5+0.5*Math.sin(cy*Math.PI*2*1.6 - waveT + phX + 0.7*Math.sin(waveT*0.37+cy*3.3));
  let d=Math.floor(wv*maxDelay) + Math.floor(A.bass*4);
  if(d>N-1)d=N-1; if(d<0)d=0;
  const idx=((S.head-d)%N+N)%N;
  const dx=(disp?(wv-0.5)*u*0.14*(0.4+P.warp):0) + (crt?Math.sin(cy*40)*u*0.002:0);
  const sy=cy*bh - (bandH*bh/Hh)/2, sh=bandH*bh/Hh;
  B.push({y0,y1,bandH,cy,wv,src:S.ring[idx],dx,sy,sh});
}

// ---- PASS 1: base delayed strips + self-visible scrolling tint band (all BLEND) ----
for(let b=0;b<nb;b++){
  const o=B[b];
  image(o.src, o.dx, o.y0, W, o.bandH, 0, o.sy, bw, o.sh);
  const briMod=lrp(-1,1,o.wv);
  if(xray){
    fill(md(H + 180*o.wv,360), 55, lrp(20,95,o.wv), en*34);
    rect(0,o.y0,W,o.bandH);
  } else {
    if(briMod>0){ fill(md(H+26*briMod,360), 42, 100, en*30*briMod); }
    else { fill(md(H+8,360),18,4, en*30*(-briMod)); }
    rect(0,o.y0,W,o.bandH);
  }
  if(crt){ fill(0,0,4, 26); for(let yy=o.y0+1;yy<o.y1;yy+=3) rect(0,yy,W,1); }
}

// ---- PASS 2: chromatic ghosts, single ADD block (no per-band blendMode toggling) ----
if(chromaOn && P.chroma>0.02){
  blendMode(ADD);
  for(let b=0;b<nb;b++){
    const o=B[b];
    tint(md(H + (b&1?185:5),360), 66, 100, 12*P.chroma);
    image(o.src, o.dx + u*0.018*P.chroma*(b&1?1:-1), o.y0, W, o.bandH, 0, o.sy, bw, o.sh);
    if(echo){ tint(md(H+90,360),50,100,10*P.chroma); image(o.src, o.dx, o.y0-o.bandH*0.5, W, o.bandH, 0, o.sy, bw, o.sh); }
  }
  blendMode(BLEND); noTint();
}

// gentle vignette for crt/xray depth (cached radial sprite)
if(crt||xray){
  if(!S.vig || S.vigKey!==W+'x'+Hh){
    if(S.vig){ try{S.vig.remove();}catch(e){} }
    S.vigKey=W+'x'+Hh; const v=createGraphics(W,Hh); v.colorMode(HSB,360,100,100,100); v.noStroke();
    const gg=v.drawingContext, rad=gg.createRadialGradient(W/2,Hh/2,u*0.22,W/2,Hh/2,u*0.74);
    rad.addColorStop(0,'rgba(0,0,0,0)'); rad.addColorStop(1,'rgba(0,0,0,0.55)');
    gg.fillStyle=rad; gg.fillRect(0,0,W,Hh); S.vig=v;
  }
  image(S.vig,0,0);
}
blendMode(BLEND); noTint();
drawingContext.imageSmoothingEnabled=true;
